CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_market_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT id,role::public.app_role FROM public.profiles WHERE role IN ('admin','worker','partner') ON CONFLICT DO NOTHING;
CREATE FUNCTION public.market_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'); $$;
CREATE TABLE public.market_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150), category text NOT NULL CHECK(category IN ('broiler','egg','livestock')), description text NOT NULL DEFAULT '', image_path text, active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.market_products TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.market_products TO authenticated; GRANT ALL ON public.market_products TO service_role;
ALTER TABLE public.market_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_market_products ON public.market_products FOR SELECT TO anon,authenticated USING(active OR public.market_is_admin());
CREATE POLICY admin_market_products ON public.market_products FOR ALL TO authenticated USING(public.market_is_admin()) WITH CHECK(public.market_is_admin());
CREATE TABLE public.market_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.market_products(id), name text NOT NULL, unit text NOT NULL CHECK(unit IN ('kg','crate','animal')), price numeric(12,2) NOT NULL CHECK(price>0), weight_kg numeric(10,3), stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), active boolean NOT NULL DEFAULT true, CHECK(unit<>'kg' OR weight_kg>0));
GRANT SELECT ON public.market_variants TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.market_variants TO authenticated; GRANT ALL ON public.market_variants TO service_role;
ALTER TABLE public.market_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_market_variants ON public.market_variants FOR SELECT TO anon,authenticated USING(public.market_is_admin() OR (active AND EXISTS(SELECT 1 FROM public.market_products p WHERE p.id=product_id AND p.active)));
CREATE POLICY admin_market_variants ON public.market_variants FOR ALL TO authenticated USING(public.market_is_admin()) WITH CHECK(public.market_is_admin());
CREATE FUNCTION public.validate_market_variant() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c text; BEGIN SELECT category INTO c FROM public.market_products WHERE id=NEW.product_id; IF c='broiler' AND (NEW.name NOT IN ('Live','Processed','Frozen') OR NEW.unit<>'kg') THEN RAISE EXCEPTION 'Broilers must use Live, Processed or Frozen and price per kg'; END IF; IF c='egg' AND (NEW.name NOT IN ('Small','Medium','Big') OR NEW.unit<>'crate') THEN RAISE EXCEPTION 'Eggs must use Small, Medium or Big and price per crate'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_market_variant BEFORE INSERT OR UPDATE ON public.market_variants FOR EACH ROW EXECUTE FUNCTION public.validate_market_variant();
CREATE TABLE public.market_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), delivery_fee numeric(12,2) NOT NULL DEFAULT 1000 CHECK(delivery_fee>=0), delivery_note text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.market_settings TO anon,authenticated; GRANT INSERT,UPDATE ON public.market_settings TO authenticated; GRANT ALL ON public.market_settings TO service_role;
ALTER TABLE public.market_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_market_settings ON public.market_settings FOR SELECT USING(true);
CREATE POLICY admin_market_settings ON public.market_settings FOR ALL TO authenticated USING(public.market_is_admin()) WITH CHECK(public.market_is_admin());
CREATE TABLE public.market_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number text NOT NULL UNIQUE DEFAULT ('AC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), access_token uuid NOT NULL DEFAULT gen_random_uuid(), customer_name text NOT NULL, email text NOT NULL, phone text NOT NULL, delivery_address text NOT NULL, items jsonb NOT NULL, subtotal numeric(12,2) NOT NULL CHECK(subtotal>0), delivery_fee numeric(12,2) NOT NULL CHECK(delivery_fee>=0), provider_fee numeric(12,2), total numeric(12,2) NOT NULL, payment_status text NOT NULL DEFAULT 'awaiting_payment' CHECK(payment_status IN ('awaiting_payment','paid','failed','refunded')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','dispatched','delivered','cancelled')), provider_reference text UNIQUE, admin_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.market_orders TO authenticated; GRANT ALL ON public.market_orders TO service_role;
ALTER TABLE public.market_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_market_orders_read ON public.market_orders FOR SELECT TO authenticated USING(public.market_is_admin());
REVOKE UPDATE ON public.market_orders FROM authenticated;
CREATE FUNCTION public.market_update_order(_id uuid,_status text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.market_orders; BEGIN IF NOT public.market_is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT * INTO o FROM public.market_orders WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF _status NOT IN ('pending','processing','dispatched','delivered','cancelled') OR length(_note)>2000 THEN RAISE EXCEPTION 'Invalid update'; END IF; IF _status IN ('processing','dispatched','delivered') AND o.payment_status<>'paid' THEN RAISE EXCEPTION 'Payment must be verified before fulfilment'; END IF; UPDATE public.market_orders SET status=_status,admin_note=_note WHERE id=_id; END; $$;
REVOKE ALL ON FUNCTION public.market_update_order(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.market_update_order(uuid,text,text) TO authenticated;
CREATE FUNCTION public.market_create_order(_customer jsonb,_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; v record; qty integer; lines jsonb:='[]'; sub numeric:=0; fee numeric:=1000; o public.market_orders; BEGIN IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'Select 1 to 30 items'; END IF; IF length(trim(_customer->>'name')) NOT BETWEEN 2 AND 150 OR coalesce(_customer->>'email','') !~ '^[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$' OR length(coalesce(_customer->>'phone','')) NOT BETWEEN 7 AND 30 OR length(trim(coalesce(_customer->>'address',''))) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'Enter valid contact and delivery details'; END IF; IF (SELECT count(*) FROM public.market_orders WHERE email=lower(_customer->>'email') AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Too many orders. Please try again later'; END IF; IF (SELECT count(DISTINCT x->>'variant_id') FROM jsonb_array_elements(_items) x) <> jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart items'; END IF; FOR item IN SELECT * FROM jsonb_array_elements(_items) LOOP qty:=(item->>'quantity')::integer; SELECT mv.*,p.name AS product_name INTO v FROM public.market_variants mv JOIN public.market_products p ON p.id=mv.product_id WHERE mv.id=(item->>'variant_id')::uuid AND mv.active AND p.active; IF NOT FOUND OR qty IS NULL OR qty<1 OR qty>v.stock THEN RAISE EXCEPTION 'Item unavailable or quantity exceeds available stock'; END IF; sub:=sub+round(v.price*qty*(CASE WHEN v.unit='kg' THEN v.weight_kg ELSE 1 END),2); lines:=lines||jsonb_build_array(jsonb_build_object('variant_id',v.id,'product',v.product_name,'variant',v.name,'quantity',qty,'unit',v.unit,'price',v.price,'weight_kg',v.weight_kg,'line_total',round(v.price*qty*(CASE WHEN v.unit='kg' THEN v.weight_kg ELSE 1 END),2))); END LOOP; SELECT delivery_fee INTO fee FROM public.market_settings WHERE id=1; fee:=coalesce(fee,1000); INSERT INTO public.market_orders(customer_name,email,phone,delivery_address,items,subtotal,delivery_fee,total) VALUES(trim(_customer->>'name'),lower(trim(_customer->>'email')),trim(_customer->>'phone'),trim(_customer->>'address'),lines,sub,fee,sub+fee) RETURNING * INTO o; RETURN jsonb_build_object('id',o.id,'token',o.access_token,'order_number',o.order_number,'subtotal',o.subtotal,'delivery_fee',o.delivery_fee,'total',o.total,'items',o.items,'payment_status',o.payment_status); END; $$;
REVOKE ALL ON FUNCTION public.market_create_order(jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.market_create_order(jsonb,jsonb) TO anon,authenticated;
CREATE POLICY market_images_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='market-products' AND (public.market_is_admin() OR EXISTS(SELECT 1 FROM public.market_products p WHERE p.active AND p.image_path=name)));
CREATE POLICY market_images_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='market-products' AND public.market_is_admin());
CREATE POLICY market_images_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='market-products' AND public.market_is_admin());